import json,collections,csv
from pathlib import Path
root=Path('docs/qa/revised-progression-2026-11-04');file=root/'results.json';x=json.loads(file.read_text());rs=x['runs'];assert len(rs)==24
routes=list(dict.fromkeys(r['route'] for r in rs));labels={'paladino':'Paladino','berserker':'Berserker','samurai':'Samurai','ninja':'Ninja','sniper':'Sniper','atirador_arcano':'Atirador Arcano','espreitador':'Espreitador','guarda_florestal':'Guarda Florestal'}
for r in rs:
 assert r['done'];assert r['reason']=='Paradoxo derrotado' or r['level']==100 and r['fullLegendary'] and r['endgameDeaths']==11
 p=[r['invested'][key] for key in ['strength','vitality','wisdom']];assert max(p)-min(p)<=1 and sum(p)==r['level']-1
 for event in r['deathEvents']:
  if event['prepared']:assert event['level']==100 and len(event['gear'])==6 and all(item and item['rarity']=='lendaria' for item in event['gear'].values())
 if r['reason']=='Paradoxo derrotado':assert len(r['bosses'])==12 and r['bosses'][-1]['region']=='Paradoxo'
 assert sum(d['prepared'] for d in r['deathEvents'])==r['endgameDeaths']
 assert len(r['deathEvents'])==r['deaths']
for route in routes:assert {r['seed'] for r in rs if r['route']==route}=={101,202,303}
x['method']=x['method'].replace('Initial Forest equipment retained on upgrades','Initial Floresta/Caverna equipment retained on upgrades; no optimization of region sets')
x['audit']={'campaigns':24,'seedsPerRoute':3,'wins':sum(r['reason']=='Paradoxo derrotado' for r in rs),'fights':sum(r['fights'] for r in rs),'deaths':sum(r['deaths'] for r in rs),'balancedPoints':True,'allQuitsAt100WithSixLegendaryAnd11PreparedDeaths':True,'preparedDeathEventsMatchCounters':True}
file.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
bfile=root/'baseline-policy-results.json';baseline=json.loads(bfile.read_text());baseline['role']='Control: earlier policy does not respond to Pacto Funebre, buff theft or charged strikes. Final analysis uses results.json.';baseline['method']=baseline['method'].replace('Initial Forest equipment retained on upgrades','Initial Floresta/Caverna equipment retained on upgrades');bfile.write_text(json.dumps(baseline,ensure_ascii=False,indent=2)+'\n')
lines=['# Guerreiro e Arqueiro contra os inimigos reformulados — 04/11/2026','','## Resultado principal','',f"24 campanhas principais, oito rotas e três sementes: **{x['audit']['wins']} vitórias**, {24-x['audit']['wins']} desistências, **{x['audit']['fights']} combates** e {x['audit']['deaths']} mortes totais. As desistências ocorreram somente com nível 100, seis equipamentos lendários e 11 mortes já nessa condição. Foram duas vitórias em 12 campanhas de Guerreiro e oito em 12 de Arqueiro.",'','| Rota | Vitórias | Níveis nas vitórias | Mortes totais por campanha | Onde pararam as campanhas sem vitória |','| --- | ---: | --- | --- | --- |']
for route in routes:
 a=[r for r in rs if r['route']==route];wins=[r for r in a if r['reason']=='Paradoxo derrotado'];lost=[r for r in a if r not in wins];stops=collections.Counter(r['deathEvents'][-1]['foe']['name'] for r in lost);lv=f"{min(r['level'] for r in wins)}–{max(r['level'] for r in wins)}" if wins else '—';lines.append(f"| {labels[route]} | {len(wins)}/3 | {lv} | {min(r['deaths'] for r in a)}–{max(r['deaths'] for r in a)} | "+('; '.join(f'{name} ({n})' for name,n in stops.items()) or 'Todas venceram')+' |')
lines+=['','Todas as campanhas sem vitória terminaram no nível 100. O contador de 11 mortes com preparação máxima é acumulado na campanha, podendo incluir inimigos diferentes; não se reinicia ao vencer um chefe. Mortes anteriores ao nível 100 ou antes de completar seis lendários não contam para esse limite.','','## Método','','O personagem começa no nível 1, escolhe a subclasse nos níveis normais e distribui os pontos equilibradamente entre Força, Vitalidade e Sabedoria. Combate, efeitos, IA inimiga, esquiva, DOTs, XP, loot, custos de habilidades e escalonamento dos equipamentos usam as funções executáveis do jogo. Foram usadas as sementes 101, 202 e 303. A política não consulta os próximos sorteios.','','A preparação foi acelerada, como autorizado: recuperação completa de HP/MP entre lutas; após cada derrota, concede-se um nível até 100. Se o mesmo alvo voltar a derrotar o personagem, concede-se também uma melhoria no slot de menor raridade. Ao nível 100, melhora-se uma peça por derrota até completar seis lendários. Fugas forçadas por Assombrar são registradas separadamente e acionam a mesma preparação. Repete-se o alvo que causou a falha.','','O craft inicial só usa materiais e moedas obtidos. Melhorias concedidas na preparação não cobram recursos. O planejamento procura itens da Floresta no começo e da Caverna depois do desbloqueio, mas conserva a região das peças já obtidas ao melhorá-las. O acessório de preparação é Colar de Raízes. Portanto, este teste não mede tempo de farm nem a dificuldade econômica do crafting.','','A estratégia usa as habilidades disponíveis conforme dano, custo, vida, controle e buffs. A preparação e as condições de encerramento são iguais às da análise acelerada do Mago. Nesta análise, a estratégia também evita buffs contra Oráculo Radiante/Imperador, espera o Pacto Fúnebre terminar antes de atacar diretamente e procura defesa contra um ataque carregado prestes a atingir. Isso não impede que reflexões automáticas acionem Pacto Fúnebre.','','Em 100 ações sem progresso ofensivo, o personagem passa turnos para deixar o combate se resolver, sem editar HP ou registrar uma morte fictícia. Nenhuma campanha encerra por limite arbitrário de turnos.','','## Por que foi necessário adaptar a estratégia','','Uma rodada de controle de 24 campanhas com a política anterior teve **0 vitórias**. Mantendo a mesma preparação e as mesmas três sementes, a política que reconhece Pacto Fúnebre e roubo/remoção de buffs teve 10 vitórias. As sequências de sorteios posteriores podem divergir porque as ações consomem RNG; não são replays com encontros idênticos do início ao fim.','','| Rota | Política anterior | Política com resposta às mecânicas |','| --- | ---: | ---: |']
for route in routes:
 old=sum(r['reason']=='Paradoxo derrotado' for r in baseline['runs'] if r['route']==route);new=sum(r['reason']=='Paradoxo derrotado' for r in rs if r['route']==route);lines.append(f'| {labels[route]} | {old}/3 | {new}/3 |')
lines+=['','Os controles estão em `qa/revised-progression-2026-11-04/baseline-policy-results.json`. Eles são preservados para comparação e não entram nas 24 campanhas principais. Ao todo, foram executadas 48 campanhas nesta análise.','','## Leitura dos gargalos','','**Avatar do Zenith:** é o maior ponto de preparação para várias rotas. Cura 4% e gera 6% de escudo por turno: com 13.830 de vida, são 553 de cura e 829 de escudo por turno, antes dos efeitos que os reduzem/impedem. Seu ataque básico tem impacto de 12%, e há queimadura de 7% e o Prisma carregado. Interromper um ataque não elimina automaticamente a aura. Berserker e Samurai pararam nele nas três sementes; o dano sustentado e a capacidade de lidar com regeneração/escudo merecem um teste de build específico.','','**Deus da Ruína:** Paladino parou nele nas três sementes. Colapso Final aplica três DOTs, e uma segunda aplicação pode completar cinco efeitos ainda ativos. Fim dos Fracos executa por quantidade de debuffs/DOTs; cura, escudo e invulnerabilidade não removem esses efeitos. A esquiva de 30% e os escudos gerados ao esquivar também aumentam a pressão. Isso favorece evitar aplicações, impedir ações ou vencer rapidamente, em vez de só aumentar a resistência. Essa é uma explicação mecânica compatível com os resultados, não um isolamento experimental de cada causa de morte.','','**Lorde da Cripta e Imperador do Eclipse:** a política anterior desperdiçava buffs ou continuava buscando dano fatal durante Pacto Fúnebre. Sniper passou de 0/3 para 3/3; Atirador Arcano, de 0/3 para 3/3. Espreitador e Guarda Florestal passaram a avançar além do Imperador. O resultado mostra a importância da decisão de combate, e não apenas dos atributos brutos.','','**Paradoxo:** o Guardião Temporal limita lutas longas, Devorar aumenta a vida máxima do inimigo e o Soberano combina reversão da última ação, armadura crescente, escudo de 75% e DOT crescente irremovível. O Espreitador chegou ao Soberano em duas sementes e parou no Guardião em uma. Ninja venceu duas; Guarda Florestal venceu duas. Evitar os gargalos anteriores não garante dano suficiente para resolver o último combate.','','## Limites e próximos testes de balanceamento','','Seis lendários não significam um conjunto otimizado. Nos Guerreiros, as cinco peças de conjunto terminaram com duas ou três peças da Caverna, misturadas à Floresta: **nenhum fechou quatro peças da Caverna**. Nos Arqueiros, houve cinco peças da Floresta ou quatro da Floresta e uma da Caverna. O Colar é separado da contagem de conjunto.','','Isso importa: a arma da Floresta concentra o orçamento ofensivo em poder de habilidade, enquanto Rajada de Flechas depende do ataque. Também não houve busca de acessórios de outras regiões para substituir a reflexão em combates com Pacto. Os resultados não demonstram que uma classe seja incapaz de vencer com outra build. Antes de aumentar dano de habilidades, os próximos testes mais úteis seriam: Guerreiro com conjunto Caverna fechado; Caçador com arma focada em ataque e conjunto ofensivo; e acessórios apropriados a cada chefe. Nenhuma alteração de balanceamento foi feita nesta análise.','','Os resultados antigos de 03/11 enfrentaram outros inimigos e usaram, em parte, preparação/equipamentos diferentes. Não é correto atribuir toda a diferença exclusivamente à força dos inimigos novos. As três sementes por rota também não estabelecem uma taxa de vitória populacional.','','## Campanhas individuais','','| Rota | Semente | Resultado | Nível | Mortes | Fugas | Combates | Mortes com preparação máxima |','| --- | ---: | --- | ---: | ---: | ---: | ---: | ---: |']
for r in rs:lines.append(f"| {labels[r['route']]} | {r['seed']} | {'Vitória' if r['reason']=='Paradoxo derrotado' else r['deathEvents'][-1]['foe']['name']} | {r['level']} | {r['deaths']} | {r['retreats']} | {r['fights']} | {r['endgameDeaths']} |")
lines+=['','## Nível em que cada chefe foi vencido','','Cada célula mostra o intervalo dos níveis nas vitórias e quantas sementes venceram aquele chefe. “—” significa que nenhuma venceu.','','| Região / chefe | '+' | '.join(labels[r] for r in routes)+' |','| --- | '+' | '.join(['---']*len(routes))+' |']
regions=list(dict.fromkeys(b['region'] for r in rs for b in r['bosses']))
order=['Floresta','Caverna','Ruinas','Pantano','Vulcao','Abismo','Fortaleza','Necropole','Citadela','Panteao','Cataclismo','Paradoxo']
for region in order:
 vals=[]
 for route in routes:
  levels=[b['level'] for r in rs if r['route']==route for b in r['bosses'] if b['region']==region];vals.append(f'{min(levels)}–{max(levels)} ({len(levels)}/3)' if levels else '—')
 lines.append('| '+region+' | '+' | '.join(vals)+' |')
lines+=['','## Inimigos com mais mortes acumuladas','','Inclui mortes durante a preparação, não apenas as 11 finais. A soma de três sementes pode ser alta mesmo para um chefe posteriormente vencido.','','| Rota | Três maiores concentrações de mortes |','| --- | --- |']
for route in routes:
 freq=collections.Counter(d['foe']['name'] for r in rs if r['route']==route for d in r['deathEvents']);lines.append('| '+labels[route]+' | '+'; '.join(f'{n}: {c}' for n,c in freq.most_common(3))+' |')
lines+=['','## Reprodução e auditoria','','- `node scripts/run-revised-progression.cjs` retoma campanhas já concluídas do arquivo de resultados.','- Para regenerar o relatório e auditar: `python3 scripts/generate-revised-progression-report.py`.','- Motor: `scripts/revised-progression-engine.js`.','- Dados e auditoria: `docs/qa/revised-progression-2026-11-04/results.json`.','- Resumo em CSV: `docs/qa/revised-progression-2026-11-04/summary.csv`.','- Validado: três sementes por rota, pontos equilibrados, eventos de mortes compatíveis com os contadores e nenhuma desistência antes da preparação máxima.']
Path('docs/analise_guerreiro_arqueiro_inimigos_2026-11-04.md').write_text('\n'.join(lines)+'\n')
with (root/'summary.csv').open('w') as f:
 out=csv.writer(f);out.writerow(['classe','rota','semente','resultado','nivel','mortes','fugas','combates','mortes_preparacao_maxima','ultimo_alvo_na_derrota'])
 for r in rs:out.writerow([r['className'],labels[r['route']],r['seed'],r['reason'],r['level'],r['deaths'],r['retreats'],r['fights'],r['endgameDeaths'],r['deathEvents'][-1]['foe']['name']])
print(x['audit'])
